package org.example.spotifymixer.runtime;
import android.content.*;import android.app.*;import android.media.*;import android.media.session.*;import android.os.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
/** Own in-process controller: native token only, never notification access or another app's session. */
public final class MediaToolsRuntime {
 public static final Handler MAIN=new Handler(Looper.getMainLooper());
 private static Context app;private static SharedPreferences prefs;
 private static final ArrayList<MediaSession> pending=new ArrayList<>();
 private static final LinkedHashMap<MediaSession.Token,MediaController> controllers=new LinkedHashMap<>();
 private static final Map<MediaSession.Token,MediaController.Callback> callbacks=new HashMap<>();
 private static final EnhancementTools.SkipGuard skipGuard=new EnhancementTools.SkipGuard();
 private static String lastTrack,notice="Waiting for a Spotify media session";
 private static AlarmManager.OnAlarmListener alarm;private static MediaSession.Token timerToken;private static long deadline;private static final Runnable TIMER=MediaToolsRuntime::fireTimer;
 public static void capture(Object wrapper){try{Field field=Class.forName("p.bqf0",false,wrapper.getClass().getClassLoader()).getDeclaredField("a");field.setAccessible(true);Object value=field.get(wrapper);if(value instanceof MediaSession)captureSession((MediaSession)value);}catch(ReflectiveOperationException|RuntimeException|LinkageError error){Diagnostics.event("Media session capture unavailable: "+error.getClass().getSimpleName());}}
 public static void captureSession(MediaSession session){MAIN.post(()->{try{if(app==null){if(pending.size()<8)pending.add(session);return;}connect(session);}catch(RuntimeException error){notice="Media session unavailable: "+error.getClass().getSimpleName();}});}
 public static void attach(Context context){if(Looper.myLooper()!=Looper.getMainLooper()){MAIN.post(()->attach(context.getApplicationContext()));return;}if(app==null){app=context.getApplicationContext();prefs=app.getSharedPreferences(Mixer.PREFS,0);for(MediaSession session:new ArrayList<>(pending))try{connect(session);}catch(RuntimeException ignored){}pending.clear();} }
 private static void connect(MediaSession session){MediaController c=session.getController();if(!c.getPackageName().equals(app.getPackageName()))return;MediaSession.Token token=c.getSessionToken();if(controllers.containsKey(token))return;
  if(controllers.size()>=8){MediaSession.Token oldest=controllers.keySet().iterator().next();remove(oldest);}
  MediaController.Callback callback=new MediaController.Callback(){public void onSessionDestroyed(){remove(token);}public void onMetadataChanged(MediaMetadata m){remember(c);}public void onPlaybackStateChanged(PlaybackState state){remember(c);}};
  controllers.put(token,c);callbacks.put(token,callback);c.registerCallback(callback,MAIN);notice="Media session connected";remember(c);
 }
 private static void remove(MediaSession.Token token){MediaController c=controllers.remove(token);MediaController.Callback cb=callbacks.remove(token);if(c!=null&&cb!=null)try{c.unregisterCallback(cb);}catch(RuntimeException ignored){}if(token.equals(timerToken))cancelTimer();}
 public static MediaController controller(){MediaController chosen=null;for(MediaController c:controllers.values()){PlaybackState s=c.getPlaybackState();if(s!=null&&s.getState()==PlaybackState.STATE_PLAYING)return c;if(s!=null&&c.getMetadata()!=null)chosen=c;}return chosen;}
 public static String status(){return controller()==null?notice:"Connected to the published Spotify media session";}
 public static boolean local(MediaController c){return c!=null&&c.getPlaybackInfo()!=null&&c.getPlaybackInfo().getPlaybackType()==MediaController.PlaybackInfo.PLAYBACK_TYPE_LOCAL;}
 public static boolean supports(long action){MediaController c=controller();PlaybackState s=c==null?null:c.getPlaybackState();return local(c)&&s!=null&&(s.getActions()&action)!=0;}
 public static String currentTrack(){MediaController c=controller();MediaMetadata m=c==null?null:c.getMetadata();if(m==null)return null;String uri=EnhancementTools.track(m.getString(MediaMetadata.METADATA_KEY_MEDIA_ID));if(uri==null)uri=EnhancementTools.track(m.getString(MediaMetadata.METADATA_KEY_MEDIA_URI));return uri;}
 public static String title(){MediaController c=controller();MediaMetadata m=c==null?null:c.getMetadata();String value=m==null?null:m.getString(MediaMetadata.METADATA_KEY_TITLE);return value==null?"No current track":value;}
 public static String artist(){MediaController c=controller();MediaMetadata m=c==null?null:c.getMetadata();String value=m==null?null:m.getString(MediaMetadata.METADATA_KEY_ARTIST);return value==null?"":value;}
 public static void pause(){if(!supports(PlaybackState.ACTION_PAUSE))throw new IllegalStateException("Local pause is not available");controller().getTransportControls().pause();}
 public static void play(){if(!supports(PlaybackState.ACTION_PLAY))throw new IllegalStateException("Local resume is not available");controller().getTransportControls().play();}
 public static void seek(long delta){if(!supports(PlaybackState.ACTION_SEEK_TO))throw new IllegalStateException("Seeking is not available for this session");MediaController c=controller();PlaybackState s=c.getPlaybackState();MediaMetadata m=c.getMetadata();long duration=m==null?0:m.getLong(MediaMetadata.METADATA_KEY_DURATION);c.getTransportControls().seekTo(EnhancementTools.seek(s.getPosition(),s.getLastPositionUpdateTime(),SystemClock.elapsedRealtime(),s.getPlaybackSpeed(),s.getState()==PlaybackState.STATE_PLAYING,duration,delta));}
 public static boolean allowSkip(int direction){return skipGuard.allow(SystemClock.elapsedRealtime(),direction,prefs!=null&&prefs.getBoolean("skip_guard_enabled",false));}
 public static void skip(int direction){long action=direction>0?PlaybackState.ACTION_SKIP_TO_NEXT:PlaybackState.ACTION_SKIP_TO_PREVIOUS;if(!supports(action))throw new IllegalStateException("Skipping is not available");if(!allowSkip(direction))throw new IllegalStateException("Press again within 1.5 seconds to skip");if(direction>0)controller().getTransportControls().skipToNext();else controller().getTransportControls().skipToPrevious();}
 public static List<MediaSession.QueueItem> queue(){MediaController c=controller();List<MediaSession.QueueItem> rows=c==null?null:c.getQueue();return rows==null?Collections.emptyList():new ArrayList<>(rows);}
 public static void jump(long id){if(!supports(PlaybackState.ACTION_SKIP_TO_QUEUE_ITEM))throw new IllegalStateException("Queue navigation is not supported");controller().getTransportControls().skipToQueueItem(id);}
 public static String queueTrack(MediaSession.QueueItem item){String uri=EnhancementTools.track(item.getDescription().getMediaId());if(uri==null&&item.getDescription().getMediaUri()!=null)uri=EnhancementTools.track(item.getDescription().getMediaUri().toString());return uri;}
 public static void snapshot(){if(prefs==null||!prefs.getBoolean("queue_undo_enabled",false))return;List<MediaSession.QueueItem> rows=queue();if(rows.isEmpty())throw new IllegalStateException("Spotify has not published queue items");JSONArray tracks=new JSONArray();for(MediaSession.QueueItem row:rows){String uri=queueTrack(row);if(uri==null)throw new IllegalStateException("Queue has unsupported items; no partial snapshot saved");tracks.put(uri);}if(!prefs.edit().putString("queue_snapshot",tracks.toString()).putLong("queue_snapshot_time",System.currentTimeMillis()).commit())throw new IllegalStateException("Could not save queue snapshot");}
 public static List<String> savedQueue(){try{JSONArray rows=new JSONArray(prefs.getString("queue_snapshot","[]"));List<String> result=new ArrayList<>();for(int i=0;i<rows.length();i++){String uri=EnhancementTools.track(rows.getString(i));if(uri==null)throw new IllegalArgumentException("Invalid saved track");result.add(uri);}return result;}catch(JSONException error){throw new IllegalStateException("Saved queue could not be read",error);}}
 public static void startTimer(int minutes){if(minutes<1||minutes>1440)throw new IllegalArgumentException("Choose 1–1440 minutes");if(!supports(PlaybackState.ACTION_PAUSE))throw new IllegalStateException("Start local playback first");cancelTimer();timerToken=controller().getSessionToken();deadline=SystemClock.elapsedRealtime()+minutes*60000L;alarm=()->fireTimer();AlarmManager am=(AlarmManager)app.getSystemService(Context.ALARM_SERVICE);try{am.set(AlarmManager.ELAPSED_REALTIME_WAKEUP,deadline,"SpotEnhancer sleep timer",alarm,MAIN);}catch(RuntimeException ignored){}MAIN.postDelayed(TIMER,minutes*60000L);notice="Sleep timer running";}
 private static void fireTimer(){if(deadline==0)return;if(SystemClock.elapsedRealtime()<deadline){MAIN.postDelayed(TIMER,Math.max(1,deadline-SystemClock.elapsedRealtime()));return;}MediaController c=controller();MediaSession.Token expected=timerToken;cancelTimer();if(prefs!=null&&prefs.getBoolean("sleep_enabled",false)&&c!=null&&c.getSessionToken().equals(expected)&&supports(PlaybackState.ACTION_PAUSE)){try{c.getTransportControls().pause();notice="Sleep timer: pause requested";}catch(RuntimeException e){notice="Sleep timer could not request pause";}}else notice="Sleep timer ended: original local session no longer available";}
 public static void cancelTimer(){boolean had=deadline!=0;MAIN.removeCallbacks(TIMER);if(alarm!=null&&app!=null)try{((AlarmManager)app.getSystemService(Context.ALARM_SERVICE)).cancel(alarm);}catch(RuntimeException ignored){}alarm=null;timerToken=null;deadline=0;if(had)notice="Sleep timer cancelled";}
 public static long remaining(){return deadline==0?0:Math.max(0,deadline-SystemClock.elapsedRealtime());}
 public static String timerStatus(){return remaining()>0?"Timer running · "+((remaining()+59999)/60000)+" minutes remaining":notice;}
 private static void remember(MediaController c){try{if(prefs==null||!prefs.getBoolean("rediscover_enabled",false))return;PlaybackState state=c.getPlaybackState();if(state==null||state.getState()!=PlaybackState.STATE_PLAYING)return;MediaMetadata m=c.getMetadata();if(m==null)return;String uri=EnhancementTools.track(m.getString(MediaMetadata.METADATA_KEY_MEDIA_ID));if(uri==null)uri=EnhancementTools.track(m.getString(MediaMetadata.METADATA_KEY_MEDIA_URI));if(uri==null||uri.equals(lastTrack))return;lastTrack=uri;JSONArray old=new JSONArray(prefs.getString("rediscover_log","[]")),next=new JSONArray();JSONObject row=new JSONObject();row.put("uri",uri);row.put("title",m.getString(MediaMetadata.METADATA_KEY_TITLE));row.put("artist",m.getString(MediaMetadata.METADATA_KEY_ARTIST));row.put("time",System.currentTimeMillis());next.put(row);for(int i=0;i<old.length()&&next.length()<1000;i++)if(!uri.equals(old.getJSONObject(i).optString("uri")))next.put(old.getJSONObject(i));prefs.edit().putString("rediscover_log",next.toString()).commit();}catch(JSONException|RuntimeException ignored){}}
 public static void refresh(){if(prefs!=null&&!prefs.getBoolean("sleep_enabled",false))cancelTimer();if(prefs!=null&&!prefs.getBoolean("rediscover_enabled",false))lastTrack=null;}
 private MediaToolsRuntime(){}
}
